69	/** Inverse of `parseIssueFilterParams`; omits every empty dimension so the
70	 *  canonical URL for "no filter" is the bare path. */
71	export function issueFilterToParams(
72	  filter: IssueFilter,
73	): Readonly<Record<string, string>> {
74	  const params: Record<string, string> = {};
75	  if (filter.projectId !== undefined) params.project = filter.projectId;
76	  if (filter.status !== undefined && filter.status.length > 0) {
77	    params.status = filter.status.join(",");
78	  }
79	  if (filter.priority !== undefined && filter.priority.length > 0) {
80	    params.priority = filter.priority.join(",");
81	  }
82	  if (filter.assigneeId !== undefined) {
83	    params.assignee = filter.assigneeId ?? UNASSIGNED_TOKEN;
84	  }
85	  if (filter.authorId !== undefined) params.author = filter.authorId;
86	  if (filter.labelIds !== undefined && filter.labelIds.length > 0) {
87	    params.label = filter.labelIds.join(",");
88	  }
89	  if (filter.query !== undefined && filter.query.length > 0) {
90	    params.q = filter.query;
91	  }
92	  if (filter.dueBefore !== undefined) params.due_before = filter.dueBefore;
93	  if (filter.includeArchived === true) params.archived = "1";
94	  return params;
95	}
