97	/** How many dimensions the user has narrowed on, for the "clear" affordance. */
98	export function activeFilterCount(filter: IssueFilter): number {
99	  return Object.keys(issueFilterToParams(filter)).length;
100	}
101	
102	export function issueFilterQueryString(filter: IssueFilter): string {
103	  const search = new URLSearchParams(issueFilterToParams(filter));
104	  const serialised = search.toString();
105	  return serialised.length > 0 ? `?${serialised}` : "";
106	}
