453	export async function findIssueById(
454	  orgId: OrgId,
455	  issueId: IssueId,
456	): Promise<Issue | null> {
457	  const row = getDb()
458	    .select()
459	    .from(issues)
460	    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
461	    .get();
462	  if (!row) return null;
463	
464	  const labels = await listLabelsForIssues(orgId, [row.id as IssueId]);
465	  return toIssue(row, (labels[row.id] ?? []).map((label) => label.id));
466	}
