487	/** Builds the shared predicate list behind `listIssues` and its count. */
488	function issueFilters(input: IssueFilterInput): readonly SQL[] {
489	  const scope: ArchiveScope = shouldFilterArchived(input)
490	    ? {}
491	    : { includeArchived: true };
492	
493	  return compact(
494	    orgPredicate(issues.orgId, input.orgId),
495	    livePredicate(issues.archivedAt, scope),
496	    input.projectId === undefined
497	      ? undefined
498	      : eq(issues.projectId, input.projectId),
499	    input.status === undefined || input.status.length === 0
500	      ? undefined
501	      : inArray(issues.status, [...input.status]),
502	    input.priority === undefined || input.priority.length === 0
503	      ? undefined
504	      : inArray(issues.priority, [...input.priority]),
505	    // `null` and `undefined` both arrive from the "Anyone" option of the
506	    // filter bar, so neither narrows the list.
507	    input.assigneeId ? eq(issues.assigneeId, input.assigneeId) : undefined,
508	    input.authorId === undefined
509	      ? undefined
510	      : eq(issues.authorId, input.authorId),
511	    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
512	    input.query === undefined
513	      ? undefined
514	      : or(
515	          like(issues.title, `%${input.query}%`),
516	          like(issues.description, `%${input.query}%`),
517	        ),
518	    input.labelIds === undefined || input.labelIds.length === 0
519	      ? undefined
520	      : inArray(
521	          issues.id,
522	          getDb()
523	            .select({ id: issueLabels.issueId })
524	            .from(issueLabels)
525	            .where(
526	              and(
527	                orgPredicate(issueLabels.orgId, input.orgId),
528	                inArray(issueLabels.labelId, [...input.labelIds]),
529	              ),
530	            ),
531	        ),
532	  );
533	}
