535	export async function listIssues(
536	  input: IssueFilterInput,
537	): Promise<Page<Issue>> {
538	  const db = getDb();
539	  const filters = issueFilters(input);
540	  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };
541	
542	  const total = db
543	    .select({ value: count() })
544	    .from(issues)
545	    .where(and(...filters))
546	    .get();
547	
548	  const rows = db
549	    .select()
550	    .from(issues)
551	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
552	    .orderBy(desc(issues.createdAt), desc(issues.id))
553	    .limit(probeLimit(input.limit))
554	    .all();
555	
556	  const labels = await listLabelsForIssues(
557	    input.orgId,
558	    rows.map((row) => row.id as IssueId),
559	  );
560	
561	  return toPage(
562	    rows,
563	    input.limit,
564	    total?.value ?? 0,
565	    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
566	    (row) => ({ id: row.id, sortValue: row.createdAt }),
567	  );
568	}
