570	/**
571	 * The list view needs comment and attachment counts per row. Two grouped
572	 * queries beat N+1 round trips, so the counts are folded in afterwards.
573	 */
574	export async function listIssuesWithRelations(
575	  input: IssueFilterInput,
576	): Promise<Page<IssueWithRelations>> {
577	  const db = getDb();
578	  const page = await listIssues(input);
579	  const ids = page.items.map((issue) => issue.id);
580	  if (ids.length === 0) {
581	    return { items: [], nextCursor: page.nextCursor, total: page.total };
582	  }
583	
584	  const commentCounts = db
585	    .select({ issueId: comments.issueId, value: count() })
586	    .from(comments)
587	    .where(
588	      and(
589	        orgPredicate(comments.orgId, input.orgId),
590	        inArray(comments.issueId, [...ids]),
591	        isNull(comments.archivedAt),
592	      ),
593	    )
594	    .groupBy(comments.issueId)
595	    .all();
596	
597	  const attachmentCounts = db
598	    .select({ issueId: attachments.issueId, value: count() })
599	    .from(attachments)
600	    .where(
601	      and(
602	        orgPredicate(attachments.orgId, input.orgId),
603	        inArray(attachments.issueId, [...ids]),
604	      ),
605	    )
606	    .groupBy(attachments.issueId)
607	    .all();
608	
609	  const labels = await listLabelsForIssues(input.orgId, ids);
610	  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
611	  const attachmentsBy = new Map(
612	    attachmentCounts.map((r) => [r.issueId, r.value]),
613	  );
614	
615	  return {
616	    items: page.items.map((issue) => ({
617	      issue,
618	      labels: labels[issue.id] ?? [],
619	      commentCount: commentsBy.get(issue.id) ?? 0,
620	      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
621	    })),
622	    nextCursor: page.nextCursor,
623	    total: page.total,
624	  };
625	}
