958	/**
959	 * Creates an issue after four gates: tenant scope, the `issue:create`
960	 * permission, a live parent project and the plan's per-project issue quota.
961	 * Only then is a number allocated and `issue.created` published — everything
962	 * reactive (notifications, search, webhooks, the audit log) hangs off that.
963	 */
964	export async function createIssue(
965	  actor: Actor,
966	  input: CreateIssueInput,
967	): Promise<Issue> {
968	  assertOrgScope(actor, input.orgId);
969	
970	  const project = requireFound(
971	    await projectRepo.findProjectById(input.orgId, input.projectId),
972	    "Project",
973	    input.projectId,
974	  );
975	  assertNotArchived("Project", project.id, project);
976	  assertCan(actor, "issue:create", projectResource(project));
977	
978	  const org = requireFound(
979	    await orgRepo.findOrgById(input.orgId),
980	    "Organization",
981	    input.orgId,
982	  );
983	  const used = await issueRepo.countIssues(input.orgId, input.projectId);
984	  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
985	    throw new Error(
986	      `Plan ${org.plan} allows no more issues in project ${project.key}`,
987	    );
988	  }
989	
990	  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
991	  const issue = await issueRepo.insertIssue(input, actor.userId, number);
992	
993	  await emit("issue.created", {
994	    ...actorEnvelope(actor),
995	    issueId: issue.id,
996	    projectId: issue.projectId,
997	    title: issue.title,
998	    assigneeId: issue.assigneeId,
999	    priority: issue.priority,
1000	  });
1001	
1002	  return issue;
1003	}
