1206	/**
1207	 * Private paging helpers shared by the repositories in this directory.
1208	 *
1209	 * Not part of the public data-access surface — repositories re-export nothing
1210	 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
1211	 * so a page boundary is stable even when two rows share a `created_at`.
1212	 */
1213	import { sql } from "drizzle-orm";
1214	import { decodeCursor, encodeCursor } from "./base-repository";
1215	import { makePage } from "@/types/common";
1216	import type { Page } from "@/types/common";
1217	import type { SQL } from "drizzle-orm";
1218	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
1219	
1220	export interface KeysetSort {
1221	  readonly sortColumn: SQLiteColumn;
1222	  readonly idColumn: SQLiteColumn;
1223	}
1224	
1225	/**
1226	 * Predicate that resumes a descending listing after `cursor`. Returns
1227	 * `undefined` for a first page or an unparseable cursor — a bad cursor
1228	 * degrades to "start from the top", never to an error page.
1229	 */
1230	export function keysetPredicate(
1231	  sort: KeysetSort,
1232	  cursor: string | null | undefined,
1233	): SQL | undefined {
1234	  if (!cursor) return undefined;
1235	  const decoded = decodeCursor(cursor);
1236	  if (!decoded) return undefined;
1237	
1238	  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
1239	}
1240	
1241	/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
1242	export function probeLimit(limit: number): number {
1243	  return Math.max(1, Math.min(limit, 100)) + 1;
1244	}
1245	
1246	/**
1247	 * Turns an over-fetched row array into a `Page`, dropping the probe row and
1248	 * deriving the next cursor from the last row that survived.
1249	 */
1250	export function toPage<TRow, TOut>(
1251	  rows: readonly TRow[],
1252	  limit: number,
1253	  total: number,
1254	  map: (row: TRow) => TOut,
1255	  cursorOf: (row: TRow) => { id: string; sortValue: string },
1256	): Page<TOut> {
1257	  const capped = Math.max(1, Math.min(limit, 100));
1258	  const hasMore = rows.length > capped;
1259	  const visible = hasMore ? rows.slice(0, capped) : rows;
1260	  const last = visible.at(-1);
1261	
1262	  const nextCursor =
1263	    hasMore && last
1264	      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
1265	      : null;
1266	
1267	  return makePage(visible.map(map), nextCursor, total);
1268	}
1269	
1270	/** Drops the `undefined` slots so `and(...)` never sees a hole. */
1271	export function compact(
1272	  ...predicates: readonly (SQL | undefined)[]
1273	): readonly SQL[] {
1274	  return predicates.filter((value): value is SQL => value !== undefined);
1275	}
