);

export function isIssueStatus(value: string): value is IssueStatus {
  return (ISSUE_STATUSES as readonly string[]).includes(value);
}

export function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return (ISSUE_STATUS_GROUPS as readonly string[]).includes(value);
}

export function statusGroupMembers(
  group: IssueStatusGroup,
): readonly IssueStatus[] {
  return group === "open" ? OPEN_ISSUE_STATUSES : CLOSED_ISSUE_STATUSES;
}

/**
