export function expandIssueStatuses(
  values: readonly string[],
): readonly IssueStatus[] {
  const expanded: IssueStatus[] = [];
  const push = (status: IssueStatus) => {
    if (!expanded.includes(status)) expanded.push(status);
  };
  for (const value of values) {
    if (isIssueStatusGroup(value)) statusGroupMembers(value).forEach(push);
