  const d = await ins({ title: "D arch", assigneeId: null });
  await issueRepo.archiveIssue(t.org.id, d.id);
  const L1 = "01HZZZZZZZZZZZZZZZZZZZZZZ1", L2 = "01HZZZZZZZZZZZZZZZZZZZZZZ2";
  getDb().insert(issueLabels).values([
    { orgId: t.org.id, issueId: a.id, labelId: L1 }, { orgId: t.org.id, issueId: a.id, labelId: L2 },
    { orgId: t.org.id, issueId: c.id, labelId: L1 }]).run();
  expect(await run("assignee=me")).toEqual(["A mine"]);
  expect(await run("assignee=none")).toEqual(["B none", "C done"]);
  expect(await run(`label=${L1},${L2}`)).toEqual(["A mine"]);
  expect(await run(`label=${L1}`)).toEqual(["A mine", "C done"]);
  expect(await run("due_before=2026-03-05")).toEqual(["A mine"]);
  expect(await run("due_before=2026-03-06")).toEqual(["A mine", "B none"]);
  expect(await run("due_before=2026-03-06T00:00:00Z")).toEqual(["A mine"]);
  expect(await run("due_before=2026-03-05T15:00:00.000Z")).toEqual([]);
  expect(await run("status=open")).toEqual(["A mine", "B none"]);
  expect(await run("status=closed")).toEqual(["C done"]);
  expect(await run("archived=only")).toEqual(["D arch"]);
  expect(await run("archived=1")).toHaveLength(4);
  expect(await run("")).toHaveLength(3);
  const viaGroup = await issueRepo.listIssues(issueFilterSchema.parse({ orgId: t.org.id, limit: 50, status: ["open"] }));
  expect(viaGroup.total).toBe(2);
  expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["bogus"] }).success).toBe(false);
  expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
  expect(orgPath("acme", "issues?assignee=me")).toBe("/acme/issues?assignee=me");
